    if n == 0:
        return s3 == s1

    dp = [[False for _ in range(n + 1)] for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(n + 1):
        if j == 0:
            dp[0][j] = True
        else:
            if s3[:j] == s2[:j]:
                dp[0][j] = True
            else:
                dp[0][j] = False

    for i in range(m + 1):
